                                  {chartDominance.highlights2024.intro && <div style={{fontSize:'10px',color:amber,fontFamily:'monospace',fontWeight:700,letterSpacing:'0.3px',marginBottom:'8px'}}>{chartDominance.highlights2024.intro}</div>}
