                              <div style={{display:'grid',gridTemplateColumns:'1fr 1fr',gap:'8px',marginBottom:'6px'}}>
                                <div style={{fontSize:'10px',color:'rgba(34,197,94,0.9)',fontFamily:'monospace',fontWeight:700,letterSpacing:'1px',textAlign:'center',padding:'6px',background:'rgba(34,197,94,0.08)',borderRadius:'8px'}}>MUSIC STREAMING</div>
                                <div style={{fontSize:'10px',color:'rgba(239,68,68,0.85)',fontFamily:'monospace',fontWeight:700,letterSpacing:'1px',textAlign:'center',padding:'6px',background:'rgba(239,68,68,0.08)',borderRadius:'8px'}}>VIDEO STREAMING</div>
                              </div>
